package org.transport.Controller;

import java.util.Map;
import org.transport.Model.User;
import org.transport.Service.UserService;
import lombok.RequiredArgsConstructor;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;


@RestController
@RequestMapping("/api/users")
@RequiredArgsConstructor
public class UserController {

    private final UserService userService;

    @PostMapping("/register")
    public ResponseEntity<User> register(@RequestBody User user) {
        User savedUser = userService.registerUser(user);
        return ResponseEntity.ok(savedUser);
    }

    @PostMapping("/login")
    public ResponseEntity<User> login(@RequestBody Map<String, String> credentials) {
        String email = credentials.get("email");
        String password = credentials.get("password");

        User user = userService.login(email, password);
        return ResponseEntity.ok(user);
    }
}

package org.transport.Controller;

import java.util.List;
import java.util.Map;
import org.transport.Model.User;
import org.transport.Model.UserWithVehicleDto;
import org.transport.Service.UserService;
import lombok.RequiredArgsConstructor;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;


@RestController
@RequestMapping("/api/users")
@RequiredArgsConstructor
public class UserController {

    private final UserService userService;

    @PostMapping("/register")
    public ResponseEntity<User> register(@RequestBody User user) {
        User savedUser = userService.registerUser(user);
        return ResponseEntity.ok(savedUser);
    }

    @PostMapping("/login")
    public ResponseEntity<User> login(@RequestBody Map<String, String> credentials) {
        String email = credentials.get("email");
        String password = credentials.get("password");

        User user = userService.login(email, password);
        return ResponseEntity.ok(user);
    }

    @GetMapping
    public ResponseEntity<List<UserWithVehicleDto>> getAllUsersWithVehicles() {
        return ResponseEntity.ok(userService.getAllUsersWithVehicles());
    }
}

package org.transport.Service;

import org.transport.Model.User;
import org.transport.Repository.UserRepository;
import lombok.RequiredArgsConstructor;
import org.springframework.stereotype.Service;

@Service
@RequiredArgsConstructor
public class UserService {

    private final UserRepository userRepository;

    public User registerUser(User user) {
        if (userRepository.findByEmail(user.getEmail()).isPresent()) {
            throw new RuntimeException("Email-ul este deja folosit!");
        }
        return userRepository.save(user);
    }

    public User login(String email, String password) {

        User user = userRepository.findByEmail(email)
                .orElseThrow(() -> new RuntimeException("Userul nu a fost gasit!"));

        if (!user.getPassword().equals(password)) {
            throw new RuntimeException("Parola gresita!");
        }

        return user;
    }
}

package org.transport.Service;

import org.transport.Model.User;
import org.transport.Model.UserWithVehicleDto;
import org.transport.Model.Vehicle;
import org.transport.Repository.UserRepository;
import org.transport.Repository.VehicleRepository;
import lombok.RequiredArgsConstructor;
import org.springframework.stereotype.Service;

import java.util.List;
import java.util.stream.Collectors;

@Service
@RequiredArgsConstructor
public class UserService {

    private final UserRepository userRepository;
    private final VehicleRepository vehicleRepository;

    public User registerUser(User user) {
        if (userRepository.findByEmail(user.getEmail()).isPresent()) {
            throw new RuntimeException("Email-ul este deja folosit!");
        }
        return userRepository.save(user);
    }

    public User login(String email, String password) {

        User user = userRepository.findByEmail(email)
                .orElseThrow(() -> new RuntimeException("Userul nu a fost gasit!"));

        if (!user.getPassword().equals(password)) {
            throw new RuntimeException("Parola gresita!");
        }

        return user;
    }

    public List<UserWithVehicleDto> getAllUsersWithVehicles() {
        return userRepository.findAll().stream()
                .map(user -> {
                    Vehicle vehicle = vehicleRepository.findByDriverId(user.getId()).orElse(null);
                    return UserWithVehicleDto.builder()
                            .id(user.getId())
                            .email(user.getEmail())
                            .firstName(user.getFirstName())
                            .lastName(user.getLastName())
                            .phoneNumber(user.getPhoneNumber())
                            .role(user.getRole())
                            .vehicle(vehicle)
                            .build();
                })
                .collect(Collectors.toList());
    }
}
